    let nb = (n + 255u) / 256u;
    let t = global_id.x;
    if (t >= nb * k) { return; }
    let b = t / k;
    let c = t % k;
    var cnt: u32 = 0u;
    for (var i: u32 = 0u; i < 256u; i = i + 1u) {
        let v = b * 256u + i;
        if (v < n) {
            if (assignments[v] == c) { cnt = cnt + 1u; }
        }
    }
    scratch[t] = cnt;
}

